import { Injectable, signal } from '@angular/core';

export interface Msg { id: number; text: string; style: 'success' | 'error'; }

@Injectable({ providedIn: 'root' })
export class MessageService {
  messages = signal<Msg[]>([]);
  private n = 0;
  show(text: string, style: 'success' | 'error') {
    const id = ++this.n;
    this.messages.update((m) => [...m, { id, text, style }]);
    setTimeout(() => this.close(id), 10000);
  }
  success(t: string) { this.show(t, 'success'); }
  error(t: string) { this.show(t, 'error'); }
  close(id: number) { this.messages.update((m) => m.filter((x) => x.id !== id)); }
}
