import { Component, inject, OnInit, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { MessageService } from './messages';

interface Manufacturer { id?: number; name: string; }
interface Car { id?: number; model: string; manufacturer?: Manufacturer; [k: string]: unknown; }
interface Rating { id?: number; rating: number; car: Car; }
interface ManufacturerRating { manufacturer: string; rating: number; }

const carName = (c: Car) => (c.manufacturer ? c.manufacturer.name + '/' + c.model : c.model);

@Component({
  selector: 'app-manufacturers',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="bar"><span>Manufacturers</span>
      <button id="gwt-debug-create-manufacturer" (click)="open({ name: '' })">Create</button></div>
    <table id="gwt-debug-manufacturers">
      <thead><tr><th>ID</th><th>Name</th><th></th><th></th></tr></thead>
      <tbody>
        @for (m of items(); track m.id) {
          <tr><td>{{ m.id }}</td><td>{{ m.name }}</td>
            <td><button (click)="open(m)">Edit</button></td>
            <td><button (click)="del(m)">Delete</button></td></tr>
        }
      </tbody>
    </table>
    @if (editing(); as e) {
      <div class="glass"></div>
      <div class="popup" id="gwt-debug-manufacturer-editor">
        <div><span>Name:</span> <input id="gwt-debug-manufacturer-input" [(ngModel)]="name"></div>
        <div><button id="gwt-debug-manufacturer-save" (click)="save()">Save</button>
          <button id="gwt-debug-manufacturer-close" (click)="editing.set(null)">Close</button></div>
      </div>
    }
  `,
})
export class ManufacturersComponent implements OnInit {
  http = inject(HttpClient);
  msg = inject(MessageService);
  items = signal<Manufacturer[]>([]);
  editing = signal<Manufacturer | null>(null);
  name = '';
  ngOnInit() {
    this.http.get<Manufacturer[]>('/api/manufacturers').subscribe({
      next: (r) => this.items.set(r), error: () => this.msg.error('Failed to load manufacturers') });
  }
  open(m: Manufacturer) { this.name = m.name; this.editing.set(m); }
  save() {
    const e = this.editing()!;
    this.http.post<Manufacturer>('/api/manufacturers', { ...e, name: this.name }).subscribe({
      next: (s) => {
        this.items.update((l) => l.some((x) => x.id === s.id) ? l.map((x) => (x.id === s.id ? s : x)) : [...l, s]);
        this.editing.set(null);
        this.msg.success('Manufacturer saved');
      },
      error: () => this.msg.error('Failed to save manufacturer'),
    });
  }
  del(m: Manufacturer) {
    if (!window.confirm('Are you sure you want to delete ' + m.name + '?')) return;
    this.http.delete('/api/manufacturers/' + m.id).subscribe({
      next: () => this.items.update((l) => l.filter((x) => x.id !== m.id)),
      error: () => this.msg.error('Failed to delete manufacturer'),
    });
  }
}

@Component({
  selector: 'app-ratings',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="bar"><span>Ratings</span>
      <button id="gwt-debug-ratingCreate" (click)="open()">Create</button></div>
    <table id="gwt-debug-ratings">
      <thead><tr><th>ID</th><th>Car</th><th>Rating</th><th></th></tr></thead>
      <tbody>
        @for (r of items(); track r.id) {
          <tr><td>{{ r.id }}</td><td>{{ name(r.car) }}</td><td>{{ r.rating }}</td>
            <td><button (click)="del(r)">Delete</button></td></tr>
        }
      </tbody>
    </table>
    @if (editing()) {
      <div class="glass"></div>
      <div class="popup">
        <div><span>Car:</span>
          <select [(ngModel)]="car">
            @for (c of cars(); track c.id) { <option [ngValue]="c">{{ name(c) }}</option> }
          </select></div>
        <div><span>Your rating:</span> <input id="gwt-debug-ratingInput" type="number" maxlength="3" [(ngModel)]="value"></div>
        <div><button id="gwt-debug-ratingSave" (click)="save()">Save</button>
          <button (click)="editing.set(false)">Close</button></div>
      </div>
    }
  `,
})
export class RatingsComponent implements OnInit {
  http = inject(HttpClient);
  msg = inject(MessageService);
  items = signal<Rating[]>([]);
  cars = signal<Car[]>([]);
  editing = signal(false);
  car: Car | null = null;
  value: number | null = null;
  name = carName;
  ngOnInit() {
    this.http.get<Rating[]>('/api/ratings').subscribe({
      next: (r) => this.items.set(r), error: () => this.msg.error('Failed to load ratings') });
  }
  open() {
    this.value = null;
    this.http.get<Car[]>('/api/cars?limit=-1').subscribe({
      next: (c) => { this.cars.set(c); this.car = c[0] ?? null; this.editing.set(true); },
      error: () => this.msg.error('Failed to load cars') });
  }
  save() {
    if (!this.car || this.value == null) return;
    this.http.post<Rating>('/api/ratings', { car: this.car, rating: this.value }).subscribe({
      next: (s) => {
        this.items.update((l) => [...l, s]);
        this.editing.set(false);
        this.msg.success('Rating saved');
      },
      error: () => this.msg.error('Failed to save rating'),
    });
  }
  del(r: Rating) {
    if (!window.confirm('Are you sure you want to delete this rating?')) return;
    this.http.delete('/api/ratings/' + r.id).subscribe({
      next: () => this.items.update((l) => l.filter((x) => x.id !== r.id)),
      error: () => this.msg.error('Failed to delete rating'),
    });
  }
}

@Component({
  selector: 'app-reports',
  standalone: true,
  template: `
    <div class="bar"><span>Average Car Rating by Manufacturer</span></div>
    <table id="gwt-debug-reports">
      <thead><tr><th>Manufacturer</th><th>Rating</th></tr></thead>
      <tbody>
        @for (r of items(); track r.manufacturer) {
          <tr><td>{{ r.manufacturer }}</td><td>{{ r.rating }}</td></tr>
        }
      </tbody>
    </table>
  `,
})
export class ReportsComponent implements OnInit {
  http = inject(HttpClient);
  msg = inject(MessageService);
  items = signal<ManufacturerRating[]>([]);
  ngOnInit() {
    this.http.get<ManufacturerRating[]>('/api/manufacturers/ratings').subscribe({
      next: (r) => this.items.set(r), error: () => this.msg.error('Failed to load report') });
  }
}
